lk."},{"name":"blind","expected":"unknown","narrative":"The pedestrian steps onto r facing the head, but the head's state is not observed.","masked":["dev.pedestrian_signal"]},{"name":"branch_1","expected":"not_applicable","narrative":"The pedestrian stepped onto the first roadway from the sidewalk while the head governing it showed walk, reached the median, and now steps onto the second roadway r while its faced head shows dont_walk_flashing without countdown: it is continuing a lawful crossing."}],"literals":[],"param_proposals":[{"name":"p.ped_signal_facing_cos","unit":"ratio","value":0.87,"convention":"cosine of the largest angle (about thirty degrees) between a pedestrian's heading and the line from its position to a pedestrian signal head at which the pedestrian counts as facing that head: the lateral offset of a far-side head from the crossing's line plus a pedestrian's heading wander","source":"MUTCD section 4E.08 (pedestrian signal heads placed at the far end of the crossing, in the pedestrian's line of sight)"},{"name":"p.ped_signal_facing_reach","unit":"m","value":40.0,"convention":"the largest distance from a pedestrian to a pedestrian signal head at which the head counts as the one across the crossing the pedestrian faces: a wide urban crossing (six lanes and a median, about 30 m) plus the head's set-back behind the far curb","source":"MUTCD section 4E.08; AASHTO Green Book urban cross-section widths"}],"gaps":[],"gap_resolutions":[]}
